-- RECORD ONLY, do not re-run (the table exists). Recovered on 2026-10-29 from the 2026-10-28 session transcript: the exact statement that built
-- event_firm_state_pit (rule pit_v1). It was typed in the SQL editor and never saved as a file. Availability date = MIN(filed_date) over all statement
-- rows of the (security, period_end); a state is the latest period whose date is strictly before the event day.
CREATE TABLE event_firm_state_pit AS WITH q AS MATERIALIZED (SELECT f.security_id, f.period_end, f.composite_score, ((f.revenue_growth_change IS NOT NULL AND f.revenue_growth_change BETWEEN -5 AND 5)::int + (f.gross_margin_change IS NOT NULL AND f.gross_margin_change BETWEEN -5 AND 5)::int + (f.operating_margin_change IS NOT NULL AND f.operating_margin_change BETWEEN -5 AND 5)::int + (f.fcf_margin_change IS NOT NULL AND f.fcf_margin_change BETWEEN -5 AND 5)::int) AS n_terms, fs.filed FROM financial_condition_score f JOIN (SELECT security_id, period_end, MIN(filed_date) AS filed FROM financial_statements GROUP BY 1, 2) fs ON fs.security_id = f.security_id AND fs.period_end = f.period_end), pairs AS (SELECT p.event_id, p.entity_id, sec.id AS security_id, e.event_date::date AS event_day FROM event_pre_context p JOIN events e ON e.id = p.event_id JOIN securities sec ON sec.entity_id = p.entity_id), pit AS (SELECT DISTINCT ON (pr.event_id, pr.entity_id) pr.event_id, pr.entity_id, q.period_end, q.filed, q.composite_score, q.n_terms FROM pairs pr LEFT JOIN q ON q.security_id = pr.security_id AND q.filed < pr.event_day ORDER BY pr.event_id, pr.entity_id, q.period_end DESC NULLS LAST), pe AS (SELECT DISTINCT ON (pr.event_id, pr.entity_id) pr.event_id, pr.entity_id, q.period_end AS pe_period_end, q.composite_score AS pe_score FROM pairs pr LEFT JOIN q ON q.security_id = pr.security_id AND q.period_end < pr.event_day ORDER BY pr.event_id, pr.entity_id, q.period_end DESC NULLS LAST) SELECT pr.event_id, pr.entity_id, pr.security_id, pr.event_day, pit.period_end, pit.filed AS filed_date, pit.composite_score, pit.n_terms, CASE WHEN pit.composite_score IS NULL THEN NULL WHEN pit.composite_score < -0.039247119206188 THEN $$deteriorating$$ WHEN pit.composite_score < -0.0078504471309634 THEN $$weakening$$ WHEN pit.composite_score < 0.00901847919266089 THEN $$stable$$ WHEN pit.composite_score < 0.040663412043068 THEN $$improving$$ ELSE $$strong$$ END AS state, pe.pe_period_end AS period_end_rule_period, CASE WHEN pe.pe_score IS NULL THEN NULL WHEN pe.pe_score < -0.039247119206188 THEN $$deteriorating$$ WHEN pe.pe_score < -0.0078504471309634 THEN $$weakening$$ WHEN pe.pe_score < 0.00901847919266089 THEN $$stable$$ WHEN pe.pe_score < 0.040663412043068 THEN $$improving$$ ELSE $$strong$$ END AS state_period_end_rule_today, $$pit_v1$$ AS rule_version, CURRENT_DATE AS computed_on FROM pairs pr JOIN pit ON pit.event_id = pr.event_id AND pit.entity_id = pr.entity_id JOIN pe ON pe.event_id = pr.event_id AND pe.entity_id = pr.entity_id;